interface QuickDB {
    target?: string | null;
    table?: string;
    fetchAll: () => Array<{ ID: string; data: unknown }>;
}

interface MongoOptions {
    url?: string | null;
    schema?: string | null;
    seperator?: string;
}

interface MySQLOptions {
    url?: string;
    host?: string;
    port?: number;
    user?: string;
    password?: string;
    database?: string;
    table?: string;
    pool?: unknown;
    waitForConnections?: boolean;
    connectionLimit?: number;
    queueLimit?: number;
}

interface FirebaseOptions {
    url?: string;
    databaseURL?: string;
    path?: string;
    ref?: string;
    app?: unknown;
    admin?: unknown;
    database?: unknown;
    credential?: unknown;
    serviceAccount?: object;
}

interface WebPanelOptions {
    port?: number;
    title?: string;
    password?: string | null;
    token?: string | null;
    readonly?: boolean;
    pollingInterval?: number;
    actions?: {
        import?: boolean;
        export?: boolean;
        deleteAll?: boolean;
    };
    theme?: {
        primary?: string;
        background?: string;
        surface?: string;
        muted?: string;
        text?: string;
    };
}

interface SetOptions {
    ttl?: number | Date;
}

interface CroxyDBOptions {
    adapter?: "jsondb" | "localstorage" | "mongo" | "yamldb" | "mysql" | "firebase";
    folder?: string;
    file?: string;
    readable?: boolean;
    noBlankData?: boolean;
    webPanel?: boolean | WebPanelOptions;
    webPanelOptions?: WebPanelOptions;
    webPort?: number;
    checkUpdates?: boolean;
    seperator?: string;
    encryptionKey?: string | null;
    mongoOptions?: MongoOptions;
    mysqlOptions?: MySQLOptions;
    firebaseOptions?: FirebaseOptions;
    adapterOptions?: MongoOptions | MySQLOptions | FirebaseOptions | Record<string, unknown>;
}

type CroxyEvent = "set" | "delete" | "expire" | "deleteAll";
type Migration<TStore extends Record<string, unknown> = Record<string, unknown>> =
    (db: CroxyDB<TStore>, context?: Record<string, unknown>) => void | Promise<void>;

interface CroxyPath<TStore extends Record<string, unknown> = Record<string, unknown>> {
    set<T = unknown>(key: string, value: T, options?: SetOptions): T;
    delete(key: string): boolean;
    fetch<T = unknown>(key: string): T | undefined;
    has(key: string): boolean;
    get<T = unknown>(key: string): T | undefined;
    push<T = unknown>(key: string, value: T): T[];
    unpush<T = unknown>(key: string, value: T): T[];
    add(key: string, value: number): number;
    subtract(key: string, value: number): number;
    setByPriority<T = unknown>(key: string, value: T, priority: number): T[];
    delByPriority<T = unknown>(key: string, priority: number): T[];
    all<T = unknown>(key?: string): T;
    deleteAll(key?: string): boolean;
    path<TNested extends Record<string, unknown> = Record<string, unknown>>(prefix: string): CroxyPath<TNested>;

    setAsync<T = unknown>(key: string, value: T, options?: SetOptions): Promise<T>;
    deleteAsync(key: string): Promise<boolean>;
    fetchAsync<T = unknown>(key: string): Promise<T | undefined>;
    hasAsync(key: string): Promise<boolean>;
    getAsync<T = unknown>(key: string): Promise<T | undefined>;
    pushAsync<T = unknown>(key: string, value: T): Promise<T[]>;
    unpushAsync<T = unknown>(key: string, value: T): Promise<T[]>;
    addAsync(key: string, value: number): Promise<number>;
    subtractAsync(key: string, value: number): Promise<number>;
    allAsync<T = unknown>(key?: string): Promise<T>;
    deleteAllAsync(key?: string): Promise<boolean>;

    on(event: CroxyEvent, listener: (...args: unknown[]) => void): this;
    off(event: CroxyEvent, listener: (...args: unknown[]) => void): this;
}

interface CroxyDB<TStore extends Record<string, unknown> = Record<string, unknown>> extends CroxyPath<TStore> {
    setCheckUpdates(boolean: boolean): boolean;
    setReadable(readable: boolean): boolean;
    setNoBlankData(noBlankData: boolean): boolean;
    setAdapter(adapter: "jsondb" | "localstorage" | "mongo" | "yamldb" | "mysql" | "firebase", options?: MongoOptions | MySQLOptions | FirebaseOptions): true | unknown;
    setFolder(name: string): true;
    setFile(name: string): true;
    setWebPanel(a: boolean, port?: number | WebPanelOptions, options?: WebPanelOptions): boolean;
    setSeperator(seperator: string): true;
    setEncryptionKey(key: string | null): true;
    registerMigration(name: string, fn: Migration<TStore>): true;
    migrate(migrations?: Array<Migration<TStore> | { name?: string; fn: Migration<TStore> }>, context?: Record<string, unknown>): Promise<true>;
    createInstance<TNewStore extends Record<string, unknown> = Record<string, unknown>>(options?: CroxyDBOptions): CroxyDB<TNewStore>;
    CroxyDB: {
        new <TNewStore extends Record<string, unknown> = Record<string, unknown>>(options?: CroxyDBOptions): CroxyDB<TNewStore>;
    };
    move(QuickDB: QuickDB): boolean;
    moveToMongo(JsonDB: object): boolean;
    moveFromMongo(MongoDB: object): boolean;
}

declare const CroxyDB: CroxyDB;

export = CroxyDB;
